<script setup>
import {computed} from 'vue'
import {Accordion,AccordionItem,AccordionTrigger,AccordionContent,Badge,Button} from '../shared/shadcn-ui.js'
const props=defineProps({lineage:Object,operation:String,snapshot:Number,error:String})
const origin=computed(()=>props.lineage?.origins?.['operation:'+props.operation])
const changes=computed(()=>(props.lineage?.events||[]).filter(e=>e.operation===props.operation))
function open(ref){const hash='#/work/'+ref.id;if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'research',hash},location.origin);else window.open('/api/plugins/research/ui'+hash,'_blank','noopener')}
</script>
<template><section class="my-4 min-w-0 rounded-lg border px-3" aria-label="接口需求来源"><div class="flex flex-wrap items-center gap-2 py-3 text-sm"><Badge variant="outline">修订 #{{snapshot}}</Badge><span>首次新增：</span><Button v-if="origin?.introduced_by" variant="link" class="h-auto whitespace-normal px-0 text-left" @click="open(origin.introduced_by)">#{{origin.introduced_by.external_id||origin.introduced_by.id}} · {{origin.introduced_by.title}}</Button><span v-else class="text-muted-foreground">未关联需求</span><span v-if="origin?.first_snapshot" class="text-xs text-muted-foreground">修订 #{{origin.first_snapshot}}</span><span v-if="origin?.last_work_item" class="text-xs text-muted-foreground">最近修改：</span><Button v-if="origin?.last_work_item" variant="link" class="h-auto whitespace-normal px-0 text-left" @click="open(origin.last_work_item)">{{origin.last_work_item.title}} · #{{origin.last_snapshot}}</Button></div><Accordion type="single" collapsible><AccordionItem value="changes"><AccordionTrigger>本修订相对上一基线的变化（{{changes.length}}）</AccordionTrigger><AccordionContent class="space-y-2"><p v-if="error" class="text-sm text-destructive">来源读取失败：{{error}}</p><p v-else-if="!changes.length" class="text-sm text-muted-foreground">{{lineage?.legacy_unknown?'历史来源未记录，不推断补写。':'此接口在本修订中没有变化。'}}</p><div v-for="event in changes" :key="event.key" class="flex flex-wrap items-center gap-2 text-sm"><Badge variant="outline">{{({added:'新增',modified:'修改',removed:'删除'})[event.change]}}</Badge><span class="min-w-0 break-all">{{event.field?event.field.in+' · '+event.field.name:'接口定义'}}</span><Button v-if="event.work_item" variant="link" class="h-auto whitespace-normal px-0 text-left" @click="open(event.work_item)">{{event.work_item.title}}</Button><span v-else class="text-muted-foreground">未关联需求</span></div></AccordionContent></AccordionItem></Accordion></section></template>
